# shellcheck shell=bash disable=SC2034,SC2154
# FEAT-045 T5: the night-shift pack (payload/pack/night-shift): the runner `biab-night-shift`, its gates, the installer
# notice and the uninstaller. One line per message, BIB_MSG[nightshift.topic.detail]='printf format' (the value carries
# its own \n; a fragment that goes into another message has none). The prompts handed to the agent and the text the
# runner writes to the owner's GitHub repository are not here: they stay English by decision (FEAT-045 D1).

BIB_MSG[nightshift.run.state_unwritable]='cannot write to %s — refusing to run\n'
BIB_MSG[nightshift.run.dry_would]='[dry run] would implement %s in %s\n'
BIB_MSG[nightshift.run.dry_nothing]='[dry run] nothing was written, no tokens were spent. Arm with: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.run.unprotected_warn]='warning: the default branch of %s has no required review on GitHub (%s); running anyway because the owner accepted that with '\''arm --unprotected-ok'\''. Tonight the PreToolUse hook is the only brake.\n'
BIB_MSG[nightshift.run.unprotected_1]='the default branch of %s has no required review on GitHub (%s).\n'
BIB_MSG[nightshift.run.unprotected_2]='Without it the PreToolUse hook is the only thing between an unattended pass and a merge, and a hook is a brake, not a lock.\n'
BIB_MSG[nightshift.run.unprotected_3]='Protect the branch (Settings > Branches or a ruleset: require a pull request with 1 approving review, include administrators),\n'
BIB_MSG[nightshift.run.unprotected_4]='or accept the risk explicitly with: sudo biab-night-shift arm --unprotected-ok\n'
BIB_MSG[nightshift.run.implementing]='implementing %s (project=%s, cli=%s, budget=$%s)\n'
BIB_MSG[nightshift.review.no_spec]='review: %s does not exist at the base commit %s\n'
BIB_MSG[nightshift.review.diff]='review: the diff of PR #%s is unreadable, empty or over %s bytes (gh exit %s, %s bytes)\n'
BIB_MSG[nightshift.review.head_moved]='review: PR #%s head moved while reading its diff (pinned %s, now %s)\n'
BIB_MSG[nightshift.review.no_answer]='review: no valid answer (exit %s); treating it as a stop\n'
BIB_MSG[nightshift.run.lowered]='running at pr tonight: %s\n'
BIB_MSG[nightshift.lower.reach]='the reach state is not valid (%s); re-arm with: sudo biab-night-shift arm'
BIB_MSG[nightshift.lower.root]='a dev/main pass never runs as root (the dev check would). Let the timer run it as the operator.'
BIB_MSG[nightshift.lower.default_dev]='the default branch of %s is called dev; dev reach needs a separate dev branch'
BIB_MSG[nightshift.lower.dev_unsound]='the dev branch of %s is missing or can be force-pushed or deleted. Fix it with: biab-night-shift dev-setup %s'
BIB_MSG[nightshift.lower.dev_behind]='dev is behind %s (%s commits). Bring it up to date with: biab-night-shift dev-sync %s'
BIB_MSG[nightshift.lower.undeclared]='%s of %s has no executable .biab/dev-check.sh that exits 0 or 1 (exit 3 means not configured). Add one, chmod +x, commit it to %s.'
BIB_MSG[nightshift.lower.dev_red]='the dev check fails on the current %s head; fix %s first. Tomorrow'\''s pass re-checks it on its own.'
BIB_MSG[nightshift.pre.review_ceiling]='the review ceiling %s is missing or invalid; nothing can merge, so nothing is spent. Reinstall the pack: sudo biab pack add night-shift\n'
BIB_MSG[nightshift.pre.summary_unwritable]='%s cannot be written; a merge nobody can read about is not made. Nothing spent.\n'
BIB_MSG[nightshift.pr.count]='pr-identity: %s open PRs into %s were opened during this pass; exactly one is needed\n'
BIB_MSG[nightshift.pr.not_ours]='pr-identity: the PR found (%s, by %s) is not the one this pass opened as %s\n'
BIB_MSG[nightshift.run.no_ci]='this repository has no CI checks, so the pass stops at the pull request (add a workflow to go further).\n'
BIB_MSG[nightshift.merge.summary]='stopped_at=summary: %s cannot be written, so PR #%s is NOT merged\n'
BIB_MSG[nightshift.merge.changed]='merge: PR #%s changed after the gates (now: %s)\n'
BIB_MSG[nightshift.merge.carry_on]='merge: gh reported a failure but PR #%s is merged; carrying on\n'
BIB_MSG[nightshift.merge.merged]='merged PR #%s into %s (%s)\n'
BIB_MSG[nightshift.status.title]='night shift\n'
BIB_MSG[nightshift.status.installed]='installed\n'
BIB_MSG[nightshift.status.not_installed]='not installed\n'
BIB_MSG[nightshift.status.mode_armed]='ARMED — passes run for real and spend your subscription\n'
BIB_MSG[nightshift.status.mode_sim]='simulating (not armed). Arm with: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.status.kill_on]='ON — no pass will run\n'
BIB_MSG[nightshift.status.kill_off]='off\n'
BIB_MSG[nightshift.status.lock_open]='NOT REQUIRED — you accepted unprotected default branches (arm --unprotected-ok); the hook is the only brake\n'
BIB_MSG[nightshift.status.lock_required]='required — a pass aborts unless the default branch needs an approving review on GitHub\n'
BIB_MSG[nightshift.status.reach_old_armed]='pr (armed before the reach ladder; re-arm to choose)\n'
BIB_MSG[nightshift.status.reach_line]='%s — %s\n'
BIB_MSG[nightshift.status.reach_lowered]='pr (asked for %s, lowered: %s)\n'
BIB_MSG[nightshift.status.budget_review]='$%s implementation + $%s independent review per pass, %ss wall clock\n'
BIB_MSG[nightshift.status.budget_invalid]='$%s per pass, %ss wall clock — review ceiling INVALID, so nothing will merge (reinstall the pack)\n'
BIB_MSG[nightshift.status.budget_plain]='$%s per pass, %ss wall clock\n'
BIB_MSG[nightshift.status.unreadable]='unreadable'
BIB_MSG[nightshift.status.none_recorded]='none recorded\n'
BIB_MSG[nightshift.arm.spend_known]='  your last 7 days, cost-equivalent: $%s (from the quota skill'\''s cache)\n'
BIB_MSG[nightshift.arm.spend_unknown]='  your last 7 days: not available (run the /quota skill once to build the cache)\n'
BIB_MSG[nightshift.reach.pr]='stops at the pull request; you review and merge'
BIB_MSG[nightshift.reach.dev]='merges to your dev branch after CI, an independent review and your dev check; main still needs you'
BIB_MSG[nightshift.reach.main]='merges to your default branch after the same gates; no lock any more, you accepted that in writing'
BIB_MSG[nightshift.arm.err_option]='arm: unknown option '\''%s'\'' (accepted: --reach pr|dev|main, --unprotected-ok)\n'
BIB_MSG[nightshift.arm.err_reach]='arm: --reach must be pr, dev or main (got '\''%s'\'')\n'
BIB_MSG[nightshift.arm.err_cli_1]='cannot arm this box: the '\''%s'\'' CLI does not declare the '\''unattended'\'' capability.\n'
BIB_MSG[nightshift.arm.err_cli_2]='Arming needs all three of: a headless mode, a per-run spend cap, and a mechanical tool guard.\n'
BIB_MSG[nightshift.arm.err_cli_3]='Simulated passes keep working — '\''biab-night-shift run'\'' will still tell you which spec it would pick.\n'
BIB_MSG[nightshift.arm.intro]='Arming the night shift means this box will run your AI unattended,\non your subscription, while you are asleep.\n\n'
BIB_MSG[nightshift.arm.reach]='Reach: %s — %s.\n\n'
BIB_MSG[nightshift.arm.cost_title]='What one pass can cost:\n'
BIB_MSG[nightshift.arm.cap_pr]='  hard cap per pass:   $%s (--max-budget-usd)\n'
BIB_MSG[nightshift.arm.cap_dev]='  hard cap per pass:   $%s implementation + $%s independent review = $%s max\n'
BIB_MSG[nightshift.arm.ceiling_ok]='  review ceiling file: $%s (%s)\n'
BIB_MSG[nightshift.arm.ceiling_bad]='  review ceiling file: MISSING OR INVALID (%s) — passes will stop before spending until the pack is reinstalled\n'
BIB_MSG[nightshift.arm.wall]='  wall-clock cap:      %s seconds, enforced by systemd (TimeoutStartSec)\n'
BIB_MSG[nightshift.arm.per_night]='  passes per night:    1, one spec, no retries\n'
BIB_MSG[nightshift.arm.stops_pr]='The pass stops at the pull request. Two things keep it there:\n'
BIB_MSG[nightshift.arm.stops_agent]='The agent itself still stops at the pull request. Two things keep it there:\n'
BIB_MSG[nightshift.arm.hook]='  a hook   allows only a push to its own branch and "gh pr create", and blocks\n           merges, releases, the GitHub API, CI edits, root and eval. A brake.\n'
BIB_MSG[nightshift.arm.github]='  GitHub   a required review on your default branch that the agent, acting as\n           you, cannot give itself. The lock. A pass aborts if it is missing.\n'
BIB_MSG[nightshift.arm.dev_text]='\nAt dev reach, after the agent has exited, this runner merges its PR into your\ndev branch only if: the PR is the one it opened tonight, it touches no danger\nzone, CI is green, an independent review finds nothing blocking, and your\n.biab/dev-check.sh passes. That merge is a BRAKE, not a lock: the runner and\nthe agent share your account and token. Main still needs you (promote).\nA project with no CI, no dev branch or no dev check stays at the pull request.\n'
BIB_MSG[nightshift.arm.main_text]='\nAt main reach the runner merges into your DEFAULT branch after the same gates.\nThe required-review lock is no longer the stop. The runner does not change\nyour branch protection: if your default branch is still locked, GitHub refuses\nthe merge and the pass ends at the pull request.\n'
BIB_MSG[nightshift.arm.unprotected_ok]='\n  --unprotected-ok: you are switching the second one OFF. Passes will run\n  against repositories with no required review, with the hook as the only\n  brake. Undo with: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.arm.type_arm]='Type ARM (in capitals) to allow real passes, anything else to cancel: '
BIB_MSG[nightshift.arm.cancel_1]='not armed (nothing was written). The box keeps simulating.\n'
BIB_MSG[nightshift.arm.gift]='\nThis box was set up as a gift. Whoever is holding it now pays for what\nit spends tonight, and may not have expected that.\nType IUNDERSTAND to confirm you are that person: '
BIB_MSG[nightshift.arm.cancel_2]='not armed (nothing was written).\n'
BIB_MSG[nightshift.arm.unlock]='\nType UNLOCK MAIN to accept that the review lock is no longer the stop: '
BIB_MSG[nightshift.arm.cancel_3]='not armed (nothing was written). Arm at dev reach instead with: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.arm.need_root_1]='the mode file must be created by root — a file you can write is not a confirmation the agent cannot forge.\n'
BIB_MSG[nightshift.arm.need_root_2]='re-run: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.arm.done_unprotected]='armed WITHOUT requiring branch protection. The hook is the only brake tonight.\n'
BIB_MSG[nightshift.arm.done_reach]='armed at reach %s.\n'
BIB_MSG[nightshift.arm.done_dev_setup]='each project needs a dev branch first, created as you (not root): biab-night-shift dev-setup <project>\n'
BIB_MSG[nightshift.arm.done_off]='armed. Turn it off again at any time with: sudo biab-night-shift disarm\n'
BIB_MSG[nightshift.arm.done_sentinel]='or stop a single night without disarming: touch %s\n'
BIB_MSG[nightshift.disarm.already]='already disarmed (the pack stays installed and the timer stays enabled).\n'
BIB_MSG[nightshift.disarm.need_root]='removing the mode file needs root. Re-run: sudo biab-night-shift disarm\n'
BIB_MSG[nightshift.disarm.done]='disarmed. The pack is still installed and the timer still fires — passes just simulate again.\n'
BIB_MSG[nightshift.dev.as_root]='%s runs as you, not as root: it uses your own gh login. Re-run without sudo.\n'
BIB_MSG[nightshift.dev.usage]='usage: biab-night-shift %s <project>   (a directory under %s)\n'
BIB_MSG[nightshift.dev.not_git]='%s: %s is not a git repository\n'
BIB_MSG[nightshift.dev.gh_login]='%s: gh is not logged in. Run: gh auth login\n'
BIB_MSG[nightshift.dev.no_repo]='%s: cannot resolve the GitHub repository or its default branch for %s\n'
BIB_MSG[nightshift.dev.default_dev]='%s: the default branch of %s is already called dev; the reach ladder needs a separate dev branch\n'
BIB_MSG[nightshift.setup.exists]='dev already exists in %s; (re)applying its protection\n'
BIB_MSG[nightshift.setup.no_tip]='dev-setup: cannot read the tip of %s in %s\n'
BIB_MSG[nightshift.setup.refused_create]='dev-setup: GitHub refused to create the dev branch in %s\n'
BIB_MSG[nightshift.setup.created]='created dev in %s from %s at %s\n'
BIB_MSG[nightshift.setup.refused_protect]='dev-setup: GitHub refused to protect dev in %s (you need admin rights on the repository)\n'
BIB_MSG[nightshift.setup.checks_copied]=', required checks copied from %s'
BIB_MSG[nightshift.setup.protected]='dev in %s is protected: no force push, no deletion%s.\n'
BIB_MSG[nightshift.setup.next]='next: commit a .biab/dev-check.sh that shows the change works (exit 0), or the project stays at the pull request.\n'
BIB_MSG[nightshift.sync.cannot]='dev-sync: cannot compare dev with %s in %s (does dev exist? run dev-setup)\n'
BIB_MSG[nightshift.sync.uptodate]='dev is up to date with %s; nothing to do.\n'
BIB_MSG[nightshift.sync.conflict]='dev-sync: GitHub could not merge %s into dev (a conflict?). Resolve it by hand on a branch and open a PR into dev.\n'
BIB_MSG[nightshift.sync.merged]='merged %s commit(s) of %s into dev.\n'
BIB_MSG[nightshift.promote.cannot]='promote: cannot compare %s with dev in %s (does dev exist? run dev-setup)\n'
BIB_MSG[nightshift.promote.nothing]='dev has nothing that %s does not; nothing to promote.\n'
BIB_MSG[nightshift.promote.cannot_open]='promote: could not open the dev -> %s pull request in %s\n'
BIB_MSG[nightshift.promote.opened]='opened %s\n'
BIB_MSG[nightshift.promote.reusing]='reusing the open promotion PR %s\n'
BIB_MSG[nightshift.promote.ahead]='dev is %s commit(s) ahead of %s. Finish it with:\n'
BIB_MSG[nightshift.promote.merge_commit]='a merge commit, never a squash merge. If %s requires an approving review, it needs one first.\n'
BIB_MSG[nightshift.usage]='Usage: biab-night-shift <command>\n\n  run       run one pass now (simulates unless the box is armed)\n  status    show what is installed, armed, disabled, and how the last pass went\n  arm       show the cost, ask for confirmation, then allow real passes (sudo)\n            --reach pr|dev|main  how far a pass may go (default dev):\n                              pr   stop at the pull request\n                              dev  merge to your dev branch after the gates\n                              main merge to your default branch (asks for\n                                   UNLOCK MAIN)\n            --unprotected-ok  also run against repos whose default branch has\n                              no required review on GitHub (hook = only brake)\n  disarm    go back to simulating without uninstalling anything (sudo)\n\n  As you, not root (uses your gh login):\n  dev-setup <project>   create and protect the project'\''s dev branch\n  dev-sync <project>    merge the default branch into dev when dev is behind\n  promote <project>     open (or reuse) the dev -> default PR and print the\n                        merge-commit command that finishes it\n'
BIB_MSG[nightshift.gate.mode_symlink]='%s is a symlink — refusing to treat it as a human confirmation (simulating instead).\n'
BIB_MSG[nightshift.gate.mode_symlink_fix]='fix it with: sudo rm -f %s && sudo biab-night-shift arm\n'
BIB_MSG[nightshift.gate.mode_content]='%s EXISTS but its contents are not the exact literal '\''%s'\'' — this pass will only simulate.\n'
BIB_MSG[nightshift.gate.mode_content_2]='nothing is armed. Re-arm deliberately with: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.gate.mode_owner]='refusing to spend — %s says '\''%s'\'' but is not root-owned mode 0644 (found owner=%s mode=%s).\n'
BIB_MSG[nightshift.gate.mode_owner_2]='a mode file the agent can write is not a human confirmation. Fix it with:\n'
BIB_MSG[nightshift.gate.ok_symlink]='%s is a symlink — not treating it as the owner'\''s acceptance.\n'
BIB_MSG[nightshift.gate.ok_content]='%s EXISTS but does not hold the exact literal '\''%s'\'' — ignoring it. Re-create it with: sudo biab-night-shift arm --unprotected-ok\n'
BIB_MSG[nightshift.gate.ok_owner]='ignoring %s — not root-owned mode 0644 (found owner=%s mode=%s); a file the agent can write is not the owner'\''s acceptance.\n'
BIB_MSG[nightshift.label.reach]='reach'
BIB_MSG[nightshift.label.main_opt-in]='main opt-in'
BIB_MSG[nightshift.gate.lit_symlink]='%s is a symlink — ignoring the %s it points at.\n'
BIB_MSG[nightshift.gate.lit_content]='%s EXISTS but does not hold one of the exact literals (%s) — ignoring the %s. Re-create it with: sudo biab-night-shift arm\n'
BIB_MSG[nightshift.gate.lit_owner]='ignoring %s — not root-owned mode 0644 (found owner=%s mode=%s); a file the agent can write is not the owner'\''s %s.\n'
BIB_MSG[nightshift.gate.budget_missing]='%s is missing, a symlink or not a regular file — no review ceiling, so nothing will merge.\n'
BIB_MSG[nightshift.gate.budget_range]='%s does not hold an amount above 0 and at most 1.00 — no review ceiling, so nothing will merge.\n'
BIB_MSG[nightshift.gate.budget_owner]='ignoring %s — not root-owned mode 0644 (found owner=%s mode=%s).\n'
BIB_MSG[nightshift.install.notice]='\n  Night shift installed — and switched OFF.\n\n  What it does once you turn it on: at 03:00 it picks ONE spec you have\n  validated and implements it with your AI. The agent itself stops at\n  the pull request: a hook blocks merges, releases, pushes to main or dev,\n  the GitHub API and CI edits — a brake. The lock is a required review on\n  your default branch, which a pass checks for and refuses to run without.\n\n  WHAT IT COSTS: a real pass spends YOUR subscription, unattended, while you\n  are asleep. Capped at $%s ($2.50 with the review at dev reach) and\n  %ss per pass, one spec per night, no retries. Nothing is spent\n  until you arm it.\n\n  Try it first — this spends nothing and tells you what it would have done:\n      biab-night-shift run\n      biab-night-shift status\n\n'
BIB_MSG[nightshift.install.armable]='  When you are ready:\n      sudo biab-night-shift arm      (shows the cost, asks you to type ARM)\n      sudo biab-night-shift disarm   (back to simulating, nothing uninstalled)\n\n  Reach: a new arm defaults to '\''dev'\''. After CI, an independent review and\n  your .biab/dev-check.sh pass, the runner merges into a dev branch ($2.50\n  max per pass). '\''arm --reach pr'\'' stops at the pull request instead. A box\n  armed before this version keeps stopping at the pull request until you\n  re-arm.\n\n'
BIB_MSG[nightshift.install.not_armable]='  NOTE about this box: it runs '\''%s'\'', which cannot be armed. Arming\n  requires a headless mode, a per-run spend cap and a mechanical tool guard,\n  and '\''%s'\'' does not offer all three. Simulated passes work fine and are\n  genuinely useful — but on this box the night shift will stay a simulation.\n\n'
BIB_MSG[nightshift.install.no_envsubst]='night-shift pack: envsubst is missing and the systemd units cannot be rendered without it. Install it and re-run: apt-get install gettext-base'
BIB_MSG[nightshift.install.no_operator]='night-shift pack: could not resolve the operator account. Run the base wizard first, then '\''biab pack add night-shift'\'' again.'
BIB_MSG[nightshift.uninstall.nothing]='night-shift pack uninstall: nothing to remove\n'
BIB_MSG[nightshift.uninstall.timer]='night-shift pack uninstall: timer was not enabled, continuing\n'
BIB_MSG[nightshift.uninstall.removing]='night-shift pack uninstall: removing %s\n'
BIB_MSG[nightshift.uninstall.complete]='night-shift pack uninstall: complete\n'
BIB_MSG[nightshift.uninstall.left_alone]='night-shift pack uninstall: left alone: the dev branch on GitHub and .biab/ in your projects (remove a dev branch yourself with: git push origin --delete dev)\n'
